type HeaderForm = {
  maGd: string;
  maPost: string;
  maQuyen: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  soHdh: string;
  soLo: string;
  ngayLo: string;
  lenhSo: string;
  lenhPo: string;
  lenhRo: string;
  maKh: string;
  maKhKey: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  maBpH: string;
  maDbH: string;
  maHsH: string;
  maXe: string;
  maNt: string;
  tyGia: string;
};

type LineForm = {
  sttRec0: string;
  maVt: string;
  tenVt: string;
  dvt: string;
  maKhoI: string;
  ton13: string;
  soLuong: string;
  gia2: string;
  tien2: string;
  giaNt2: string;
  tienNt2: string;
  maThue: string;
  thueSuat: string;
  thueNt: string;
};

const POST_VALUES = ['3', '5', '7', '9'] as const;

function today(): string {
  return format(new Date(), 'yyyy-MM-dd');
}

function emptyHeader(): HeaderForm {
  return {
    maGd: '4',
    maPost: '3',
    maQuyen: '',
    ngayCt: today(),
    ngayLct: today(),
    soCt: '',
    soHdh: '',
    soLo: '',
    ngayLo: '',
    lenhSo: '',
    lenhPo: '',
    lenhRo: '',
    maKh: '',
    maKhKey: '',
    ongBa: '',
    diaChi: '',
    dienGiai: '',
    maBpH: '',
    maDbH: '',
    maHsH: '',
    maXe: '',
    maNt: '',
    tyGia: '',
  };
}

function emptyLine(): LineForm {
  return {
    sttRec0: '',
    maVt: '',
    tenVt: '',
    dvt: '',
    maKhoI: '',
    ton13: '',
    soLuong: '',
    gia2: '',
    tien2: '',
    giaNt2: '',
    tienNt2: '',
    maThue: '',
    thueSuat: '',
    thueNt: '',
  };
}

function blank(value: string): boolean {
  return value.trim() === '';
}

function num(value: string): number {
  if (blank(value)) return 0;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function nullText(value: string): string | null {
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

function nullNumber(value: string): number | null {
  if (blank(value)) return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function roundAway(value: number, digits: number): number {
  if (!Number.isFinite(value)) return 0;
  const factor = 10 ** digits;
  const scaled = value * factor;
  const sign = scaled < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(scaled))) / factor;
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function lineTotal(line: LineForm): number {
  return num(line.tienNt2) + num(line.thueNt);
}

function keepPost(value: string): string {
  return POST_VALUES.includes(value as (typeof POST_VALUES)[number]) ? value : '3';
}

function headerFromDetail(data: ShippingOrderDetail): HeaderForm {
  return {
    maGd: data.maGd === '4' ? '4' : '4',
    maPost: keepPost(data.maPost),
    maQuyen: data.maQuyen ?? '',
    ngayCt: data.ngayCt ?? '',
    ngayLct: data.ngayLct ?? '',
    soCt: data.soCt ?? '',
    soHdh: data.soHdh ?? '',
    soLo: data.soLo ?? '',
    ngayLo: data.ngayLo ?? '',
    lenhSo: data.lenhSo ?? '',
    lenhPo: data.lenhPo ?? '',
    lenhRo: data.lenhRo ?? '',
    maKh: data.maKh ?? '',
    maKhKey: '',
    ongBa: data.ongBa ?? '',
    diaChi: data.diaChi ?? '',
    dienGiai: data.dienGiai ?? '',
    maBpH: data.maBpH ?? '',
    maDbH: data.maDbH ?? '',
    maHsH: data.maHsH ?? '',
    maXe: data.maXe ?? '',
    maNt: data.maNt ?? '',
    tyGia: data.tyGia == null ? '' : String(data.tyGia),
  };
}

function lineFromDetail(line: ShippingOrderDetail['lines'][number]): LineForm {
  return {
    sttRec0: line.sttRec0 ?? '',
    maVt: line.maVt ?? '',
    tenVt: line.tenVt ?? '',
    dvt: line.dvt ?? '',
    maKhoI: line.maKhoI ?? '',
    ton13: line.ton13 == null ? '' : String(line.ton13),
    soLuong: line.soLuong == null ? '' : String(line.soLuong),
    gia2: line.gia2 == null ? '' : String(line.gia2),
    tien2: line.tien2 == null ? '' : String(line.tien2),
    giaNt2: line.giaNt2 == null ? '' : String(line.giaNt2),
    tienNt2: line.tienNt2 == null ? '' : String(line.tienNt2),
    maThue: line.maThue ?? '',
    thueSuat: line.thueSuat == null ? '' : String(line.thueSuat),
    thueNt: line.thueNt == null ? '' : String(line.thueNt),
  };
}

function lineFromPull(line: ShippingOrderFromOrderLine): LineForm {
  return {
    ...emptyLine(),
    maVt: line.maVt ?? '',
    tenVt: line.tenVt ?? '',
    dvt: line.dvt ?? '',
    soLuong: line.soLuong == null ? '' : String(line.soLuong),
    tienNt2: line.tienNt2 == null ? '' : String(line.tienNt2),
  };
}

function toBody(header: HeaderForm, lines: LineForm[]): ShippingOrderWriteBody {
  return {
    maGd: '4',
    maPost: keepPost(header.maPost),
    maCt: 'HDL',
    maQuyen: nullText(header.maQuyen),
    ngayCt: nullText(header.ngayCt),
    ngayLct: nullText(header.ngayLct),
    soHdh: nullText(header.soHdh),
    soCt: nullText(header.soCt),
    soLo: nullText(header.soLo),
    ngayLo: nullText(header.ngayLo),
    lenhSo: nullText(header.lenhSo),
    lenhPo: nullText(header.lenhPo),
    lenhRo: nullText(header.lenhRo),
    maKh: header.maKh.trim(),
    ongBa: nullText(header.ongBa),
    diaChi: nullText(header.diaChi),
    dienGiai: nullText(header.dienGiai),
    maBpH: nullText(header.maBpH),
    maDbH: nullText(header.maDbH),
    maHsH: nullText(header.maHsH),
    maXe: nullText(header.maXe),
    maNt: nullText(header.maNt),
    tyGia: blank(header.tyGia) ? 0 : num(header.tyGia),
    lines: lines.map(line => ({
      sttRec0: nullText(line.sttRec0),
      maVt: nullText(line.maVt),
      tenVt: nullText(line.tenVt),
      dvt: nullText(line.dvt),
      maKhoI: line.maKhoI.trim(),
      ton13: nullNumber(line.ton13),
      soLuong: nullNumber(line.soLuong),
      gia2: nullNumber(line.gia2),
      tien2: nullNumber(line.tien2),
      giaNt2: nullNumber(line.giaNt2),
      tienNt2: nullNumber(line.tienNt2),
      maThue: nullText(line.maThue),
      thueSuat: nullNumber(line.thueSuat),
      thueNt: nullNumber(line.thueNt),
      tienNt3: lineTotal(line),
    })),
  };
}

const HdlFormPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNew = !sttRec;
  const isReadOnly = isView;
  const customerSearch = useMemo(() => createCustomerSearchConfig(), []);
  const materialSearch = useMemo(() => createMaterialSearchConfig(), []);

  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [header, setHeader] = useState<HeaderForm>(emptyHeader);
  const [lines, setLines] = useState<LineForm[]>([]);
  const [loadError, setLoadError] = useState('');
  const [banner, setBanner] = useState('');
  const [saving, setSaving] = useState(false);
  const [pulling, setPulling] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const source = sttRec || copyFrom;
    if (!source) {
      setHeader(emptyHeader());
      setLines([]);
      setLoadError('');
      markClean();
      return () => { cancelled = true; };
    }
    getShippingOrder(source)
      .then(data => {
        if (cancelled) return;
        setHeader(headerFromDetail(data));
        setLines((data.lines ?? []).map(lineFromDetail));
        setLoadError('');
        markClean();
      })
      .catch(err => {
        if (!cancelled) {
          setLoadError(err instanceof Error ? err.message : 'Không tải được lệnh xuất hàng');
        }
      });
    return () => { cancelled = true; };
  }, [sttRec, copyFrom]);

  const tSoLuong = lines.reduce((sum, line) => sum + num(line.soLuong), 0);
  const tTienNt2 = roundAway(lines.reduce((sum, line) => sum + num(line.tienNt2), 0), 0);
  const tTien2 = roundAway(lines.reduce((sum, line) => sum + num(line.tien2), 0), 0);
  const tThueNt = lines.reduce((sum, line) => sum + num(line.thueNt), 0);
  const tTienNt3 = lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const title = isView ? 'Xem lệnh xuất hàng' : isNew ? 'Thêm lệnh xuất hàng' : 'Sửa lệnh xuất hàng';
  const hideBody = Boolean(loadError);

  const patchHeader = (patch: Partial<HeaderForm>) => {
    markDirty();
    setHeader(prev => ({ ...prev, ...patch }));
  };

  const patchLine = (index: number, patch: Partial<LineForm>) => {
    markDirty();
    setLines(prev => prev.map((line, i) => (i === index ? { ...line, ...patch } : line)));
  };

  const fillAmount = (index: number) => {
    setLines(prev => prev.map((line, i) => {
      if (i !== index) return line;
      const patch: Partial<LineForm> = {};
      if (blank(line.tien2) && !blank(line.soLuong) && !blank(line.gia2)) {
        const qty = Number(line.soLuong);
        const price = Number(line.gia2);
        if (Number.isFinite(qty) && Number.isFinite(price)) patch.tien2 = String(roundAway(qty * price, 0));
      }
      if (blank(line.tienNt2) && !blank(line.soLuong) && !blank(line.giaNt2)) {
        const qty = Number(line.soLuong);
        const price = Number(line.giaNt2);
        if (Number.isFinite(qty) && Number.isFinite(price)) patch.tienNt2 = String(roundAway(qty * price, 0));
      }
      return Object.keys(patch).length > 0 ? { ...line, ...patch } : line;
    }));
    markDirty();
  };

  const onPull = async () => {
    if (isReadOnly || pulling) return;
    setPulling(true);
    setBanner('');
    try {
      const data = await pullShippingOrderFromOrder({
        soHdh: header.soHdh.trim(),
        ngayCt: header.ngayCt.trim() || undefined,
        sttRec: sttRec || undefined,
      });
      setLines((data.lines ?? []).map(lineFromPull));
      setHeader(prev => ({
        ...prev,
        maKh: data.maKh ?? '',
        maKhKey: '',
        maDbH: data.maDbH ?? '',
        maBpH: data.maBpH ?? '',
        maHsH: data.maHsH ?? '',
        ongBa: data.ongBa ?? '',
        diaChi: data.diaChi ?? '',
        soHdh: data.soHdh ?? prev.soHdh.trim(),
      }));
      markDirty();
    } catch (err) {
      setBanner(err instanceof Error ? err.message : 'Không tồn tại đơn hàng này');
    } finally {
      setPulling(false);
    }
  };

  const save = async () => {
    if (blank(header.maKh)) {
      setBanner('Bạn chưa nhập mã đối tượng');
      return;
    }
    if (lines.length > 0 && lines.some(line => blank(line.maKhoI))) {
      setBanner('Bạn chưa nhập kho xuất ');
      return;
    }
    setBanner('');
    const body = toBody(header, lines);
    setSaving(true);
    try {
      if (sttRec && !isView) await updateShippingOrder(sttRec, body);
      else await createShippingOrder(body);
      markClean();
      dispatchAppToast(dispatch, { message: 'Đã lưu lệnh xuất hàng', type: 'success' });
      navigate('/bh/hdl');
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Lưu thất bại',
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={df.page} data-testid="ct-hdl-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={isReadOnly}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        saveTestId="ct-hdl-save-btn"
        onBack={() => guardedNavigate(() => navigate('/bh/hdl'))}
        onSave={hideBody || isReadOnly ? undefined : save}
      />
      {(loadError || banner) ? <div className={df.errorBanner}>{loadError || banner}</div> : null}
      {!hideBody && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Loại giao dịch</label>
                <Select
                  data-testid="ct-hdl-field-maGd"
                  disabled={isReadOnly}
                  value={header.maGd}
                  onChange={e => patchHeader({ maGd: e.target.value })}
                  options={[{ value: '4', label: 'Lệnh xuất hàng' }]}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Trạng thái</label>
                <Select
                  data-testid="ct-hdl-field-maPost"
                  disabled={isReadOnly}
                  value={header.maPost}
                  onChange={e => patchHeader({ maPost: e.target.value })}
                  options={[
                    { value: '3', label: 'Lập lệnh xuất hàng' },
                    { value: '5', label: 'Lệnh xuất hàng đã duyệt' },
                    { value: '7', label: 'Lệnh đang xuất hàng' },
                    { value: '9', label: 'Đóng lệnh' },
                  ]}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Quyền số</label>
                <Input data-testid="ct-hdl-field-maQuyen" disabled={isReadOnly} value={header.maQuyen} onChange={e => patchHeader({ maQuyen: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày</label>
                <Input type="date" data-testid="ct-hdl-field-ngayCt" disabled={isReadOnly} value={header.ngayCt} onChange={e => patchHeader({ ngayCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày lập</label>
                <Input type="date" data-testid="ct-hdl-field-ngayLct" disabled={isReadOnly} value={header.ngayLct} onChange={e => patchHeader({ ngayLct: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lệnh</label>
                <Input maxLength={30} data-testid="ct-hdl-field-soCt" disabled={isReadOnly} value={header.soCt} onChange={e => patchHeader({ soCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số đơn hàng</label>
                <Input data-testid="ct-hdl-field-soHdh" disabled={isReadOnly} value={header.soHdh} onChange={e => patchHeader({ soHdh: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lô</label>
                <Input data-testid="ct-hdl-field-soLo" disabled={isReadOnly} value={header.soLo} onChange={e => patchHeader({ soLo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày lô</label>
                <Input type="date" data-testid="ct-hdl-field-ngayLo" disabled={isReadOnly} value={header.ngayLo} onChange={e => patchHeader({ ngayLo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lệnh (Lenh_So)</label>
                <Input maxLength={30} data-testid="ct-hdl-field-lenhSo" disabled={isReadOnly} value={header.lenhSo} onChange={e => patchHeader({ lenhSo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số PO</label>
                <Input maxLength={30} data-testid="ct-hdl-field-lenhPo" disabled={isReadOnly} value={header.lenhPo} onChange={e => patchHeader({ lenhPo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số RO</label>
                <Input maxLength={30} data-testid="ct-hdl-field-lenhRo" disabled={isReadOnly} value={header.lenhRo} onChange={e => patchHeader({ lenhRo: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Khách hàng</label>
                <SearchInput
                  config={customerSearch}
                  value={header.maKhKey}
                  primaryDisplay={header.maKh}
                  disabled={isReadOnly}
                  showLabel={false}
                  data-testid="ct-hdl-field-maKh"
                  onChange={(item: CustomerDto) => patchHeader({ maKh: item.code, maKhKey: item.customerId })}
                  onClear={() => patchHeader({ maKh: '', maKhKey: '' })}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Người giao dịch</label>
                <Input data-testid="ct-hdl-field-ongBa" disabled={isReadOnly} value={header.ongBa} onChange={e => patchHeader({ ongBa: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Địa chỉ</label>
                <Input maxLength={200} data-testid="ct-hdl-field-diaChi" disabled={isReadOnly} value={header.diaChi} onChange={e => patchHeader({ diaChi: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Diễn giải</label>
                <Input data-testid="ct-hdl-field-dienGiai" disabled={isReadOnly} value={header.dienGiai} onChange={e => patchHeader({ dienGiai: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Phòng ban</label>
                <Input maxLength={30} data-testid="ct-hdl-field-maBpH" disabled={isReadOnly} value={header.maBpH} onChange={e => patchHeader({ maBpH: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Địa bàn</label>
                <Input maxLength={30} data-testid="ct-hdl-field-maDbH" disabled={isReadOnly} value={header.maDbH} onChange={e => patchHeader({ maDbH: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Nhân sự</label>
                <Input maxLength={30} data-testid="ct-hdl-field-maHsH" disabled={isReadOnly} value={header.maHsH} onChange={e => patchHeader({ maHsH: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Xe</label>
                <Input maxLength={30} data-testid="ct-hdl-field-maXe" disabled={isReadOnly} value={header.maXe} onChange={e => patchHeader({ maXe: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Ngoại tệ</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Ngoại tệ</label>
                <Input maxLength={3} data-testid="ct-hdl-field-maNt" disabled={isReadOnly} value={header.maNt} onChange={e => patchHeader({ maNt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Tỷ giá</label>
                <Input inputMode="decimal" data-testid="ct-hdl-field-tyGia" disabled={isReadOnly} value={header.tyGia} onChange={e => patchHeader({ tyGia: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section} data-testid="ct-hdl-pull">
            <h2 className={df.sectionTitle}>Lấy từ đơn hàng</h2>
            <Button
              variant="primary"
              data-testid="ct-hdl-pull-order-btn"
              disabled={isReadOnly || pulling}
              loading={pulling}
              onClick={() => { void onPull(); }}
            >
              Lấy từ đơn hàng
            </Button>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng phiếu</h2>
            {!isReadOnly && (
              <button
                type="button"
                className={df.btnAddLine}
                data-testid="ct-hdl-line-add-btn"
                onClick={() => {
                  markDirty();
                  setLines(prev => [...prev, emptyLine()]);
                }}
              >
                Thêm dòng
              </button>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable}>
                <thead>
                  <tr>
                    <th>Hàng hoá</th>
                    <th>Tên hàng hoá</th>
                    <th>ĐVT</th>
                    <th>Kho</th>
                    <th>Tồn</th>
                    <th>Số lượng</th>
                    <th>Giá bán</th>
                    <th>Thành tiền</th>
                    <th>Giá bán NT</th>
                    <th>Thành tiền NT</th>
                    <th>VAT</th>
                    <th>% VAT</th>
                    <th>Tiền thuế</th>
                    <th>Tổng cộng</th>
                    {!isReadOnly && <th />}
                  </tr>
                </thead>
                <tbody>
                  {lines.map((line, index) => (
                    <tr key={`${line.sttRec0}-${index}`}>
                      <td>
                        <SearchInput
                          config={materialSearch}
                          value={line.maVt}
                          primaryDisplay={line.maVt}
                          secondaryDisplay={line.tenVt}
                          disabled={isReadOnly}
                          showLabel={false}
                          data-testid={`ct-hdl-line-${index}-maVt`}
                          onChange={(item: MaterialDto) => patchLine(index, {
                            maVt: item.code,
                            tenVt: item.name ?? '',
                            dvt: item.unitCode ?? '',
                          })}
                          onClear={() => patchLine(index, { maVt: '', tenVt: '', dvt: '' })}
                        />
                      </td>
                      <td data-testid={`ct-hdl-line-${index}-tenVt`}>{line.tenVt}</td>
                      <td data-testid={`ct-hdl-line-${index}-dvt`}>{line.dvt}</td>
                      <td>
                        <Input
                          data-testid={`ct-hdl-line-${index}-maKhoI`}
                          disabled={isReadOnly}
                          value={line.maKhoI}
                          onChange={e => patchLine(index, { maKhoI: e.target.value })}
                        />
                      </td>
                      <td data-testid={`ct-hdl-line-${index}-ton13`}>{line.ton13}</td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-soLuong`}
                          disabled={isReadOnly}
                          value={line.soLuong}
                          onChange={e => patchLine(index, { soLuong: e.target.value })}
                          onBlur={() => fillAmount(index)}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-gia2`}
                          disabled={isReadOnly}
                          value={line.gia2}
                          onChange={e => patchLine(index, { gia2: e.target.value })}
                          onBlur={() => fillAmount(index)}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-tien2`}
                          disabled={isReadOnly}
                          value={line.tien2}
                          onChange={e => patchLine(index, { tien2: e.target.value })}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-giaNt2`}
                          disabled={isReadOnly}
                          value={line.giaNt2}
                          onChange={e => patchLine(index, { giaNt2: e.target.value })}
                          onBlur={() => fillAmount(index)}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-tienNt2`}
                          disabled={isReadOnly}
                          value={line.tienNt2}
                          onChange={e => patchLine(index, { tienNt2: e.target.value })}
                        />
                      </td>
                      <td>
                        <Input
                          data-testid={`ct-hdl-line-${index}-maThue`}
                          disabled={isReadOnly}
                          value={line.maThue}
                          onChange={e => patchLine(index, { maThue: e.target.value })}
                        />
                      </td>
                      <td data-testid={`ct-hdl-line-${index}-thueSuat`}>{line.thueSuat}</td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hdl-line-${index}-thueNt`}
                          disabled={isReadOnly}
                          value={line.thueNt}
                          onChange={e => patchLine(index, { thueNt: e.target.value })}
                        />
                      </td>
                      <td data-testid={`ct-hdl-line-${index}-tienNt3`}>{showMoney(lineTotal(line))}</td>
                      {!isReadOnly && (
                        <td>
                          <button
                            type="button"
                            className={df.btnDeleteLine}
                            data-testid={`ct-hdl-line-${index}-remove`}
                            onClick={() => {
                              markDirty();
                              setLines(prev => prev.filter((_, i) => i !== index));
                            }}
                          >
                            Xóa dòng
                          </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <div className={df.totalBlock} data-testid="ct-hdl-field-tSoLuong">Số lượng: {showMoney(tSoLuong)}</div>
            <div className={df.totalBlock} data-testid="ct-hdl-field-tTienNt2">Tiền hàng: {showMoney(tTienNt2)}</div>
            <div className={df.totalBlock} data-testid="ct-hdl-field-tTien2">Tiền hàng VND: {showMoney(tTien2)}</div>
            <div className={df.totalBlock} data-testid="ct-hdl-field-tThueNt">Tiền thuế: {showMoney(tThueNt)}</div>
            <div className={df.totalBlock} data-testid="ct-hdl-field-tTienNt3">Tổng cộng: {showMoney(tTienNt3)}</div>
          </div>
        </>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default HdlFormPage;
